if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$category=trim($_POST['category']??'');$status=$_POST['status']??'active';$image=vendor_image_upload($_FILES['image']??null,$error);if(!$name||$price<0||$stock<0){$error='Please enter valid product details.';}elseif(!$error){$s=$conn->prepare("INSERT INTO products(vendor_id,name,description,price,stock,image,category,status) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param('issdisss',$vendor_id,$name,$description,$price,$stock,$image,$category,$status);if($s->execute()){header('Location: products.php');exit;} $error='Could not create product: '.$s->error;}}
